    sample_size = sum(MEASURED_N, na.rm = TRUE),
    .groups = "drop"
  ) |&gt;
  filter(!is.na(LATITUDE), !is.na(LONGITUDE))

# Create the map with hexbins
leaflet() |&gt;
  addProviderTiles(providers$CartoDB.Positron) |&gt;
  addHexbin(
    lng = hexbin_data$LONGITUDE,
    lat = hexbin_data$LATITUDE,
    radius = 5,
    options = hexbinOptions(
      colorRange = c("#440154", "#21918c", "#fde725"), # viridis-ish
      radiusRange = c(1, 5),
      colorScaleExtent = c(
        min(hexbin_data$sample_size, na.rm = TRUE),
        max(hexbin_data$sample_size, na.rm = TRUE)
      )
    )
  )








